        s->zs.next_out = ob; s->zs.avail_out = sizeof(ob);
        deflate(&s->zs, Z_NO_FLUSH);
        size_t have = sizeof(ob) - s->zs.avail_out;
        if (have) { zos_w(c, s, ob, have); s->entries->csize += (uint32_t)have; }
        if (s->zs.avail_out) break;
