{
    bmap *m = bm_of(c->self);
    const char *k = S(c->args[0].l);
    for (int i = 0; i < m->n; i++)
        if (!strcmp(m->e[i].k, k)) {
            free(m->e[i].k);
            memmove(&m->e[i], &m->e[i + 1], (size_t)(m->n - i - 1) * sizeof(bent));
            m->n--;
            return;
        }
}
