static void Matrix_postScale(tl_jcall *c) { float *f=mat_of(c->self),t[9]={0},r[9]; t[0]=c->args[0].f;t[4]=c->args[1].f;t[8]=1; mat_mul(r,f,t); memcpy(f,r,36); c->ret=vz(true); }
