    r0[1] = y*x*ic + z*si; r0[5] = y*y*ic + co;   r0[9]  = y*z*ic - x*si; r0[13] = 0;
    r0[2] = x*z*ic - y*si; r0[6] = y*z*ic + x*si; r0[10] = z*z*ic + co;   r0[14] = 0;
    r0[3] = 0;             r0[7] = 0;             r0[11] = 0;             r0[15] = 1;
    float rr[16];
    for (int i = 0; i < 4; i++)
        for (int j = 0; j < 4; j++) {
            float s = 0;
            for (int k = 0; k < 4; k++) s += m[i + k * 4] * r0[k + j * 4];
            rr[i + j * 4] = s;
        }
    memcpy(m, rr, sizeof rr);
