        jobj *w = tl_jni_call(l, "get", "(I)Ljava/lang/Object;", a).l;
        if (!w) continue;
        jvalue arg[4] = { { .j = 0, .l = e }, { .i = 0 }, { .i = 0 }, { .i = 0 } };
        char sig[96];
